import * as LucideIcons from "lucide-react";

/**
 * Dynamically resolves a Lucide icon component by name string.
 * @param {string} iconName - The string name of the Lucide icon (e.g. "Droplet", "Wind", "FileText").
 * @param {React.Component} defaultIcon - The fallback component to return if name isn't found.
 * @returns {React.Component} The Lucide icon component.
 */
export function getLucideIcon(iconName, defaultIcon = LucideIcons.FileText) {
  if (!iconName) return defaultIcon;
  return LucideIcons[iconName] || defaultIcon;
}

export const COMMON_CHIP_ICONS = {
  FileText: LucideIcons.FileText,
  Code2: LucideIcons.Code2,
  Table2: LucideIcons.Table2,
  ShieldCheck: LucideIcons.ShieldCheck,
  MessageSquareText: LucideIcons.MessageSquareText,
  Globe: LucideIcons.Globe,
  Cpu: LucideIcons.Cpu,
  HardDrive: LucideIcons.HardDrive,
  ClipboardCheck: LucideIcons.ClipboardCheck,
};
